

import sys
import marshal
import types
import struct
import hashlib
import io

try:
    import codecs
    sys.stdout = codecs.getwriter('utf-8')(sys.stdout.buffer, 'replace')
    sys.stderr = codecs.getwriter('utf-8')(sys.stderr.buffer, 'replace')
except Exception:
    pass

COMP_NAMES = {0: "none", 1: "zlib", 2: "gzip", 3: "bz2", 4: "lzma"}

_CONTAINER = bytes.fromhex("")

def _decompress(payload, comp_id):
    if comp_id == 0:
        return payload
    elif comp_id == 1:
        import zlib
        return zlib.decompress(payload)
    elif comp_id == 2:
        import gzip
        buf = io.BytesIO(payload)
        with gzip.GzipFile(fileobj=buf, mode='rb') as f:
            return f.read()
    elif comp_id == 3:
        import bz2
        return bz2.decompress(payload)
    elif comp_id == 4:
        import lzma
        return lzma.decompress(payload)
    return payload

def _parse_container(data):
    MAGIC = b"MRSH"
    HEADER_SIZE = 24

    if len(data) < HEADER_SIZE:
        raise ValueError("Container too small")

    header = struct.unpack(">4s H H B B I B B Q", data[:HEADER_SIZE])
    magic, version, _, py_major, py_minor = header[0], header[1], header[2], header[3], header[4]

    if magic != MAGIC:
        raise ValueError("Invalid container")
    if version != 1:
        raise ValueError("Incompatible version")

    layer_count, comp_id, obf_id, payload_len = header[5:9]
    checksum = data[HEADER_SIZE:HEADER_SIZE + 32]
    payload = data[HEADER_SIZE + 32:HEADER_SIZE + 32 + payload_len]

    if hashlib.sha256(payload).digest() != checksum:
        raise ValueError("Checksum mismatch")

    return {
        "python_major": py_major,
        "python_minor": py_minor,
        "layer_count": layer_count,
        "compression_id": comp_id,
        "obfuscation_id": obf_id,
        "payload": payload,
    }

def _deobfuscate(payload, obf_id):
    if obf_id == 0:
        return payload
    import base64
    payload = base64.b64decode(payload)
    key = b"MARSH_KEY_2024"
    key_len = len(key)
    result = bytearray()
    for i, byte in enumerate(payload):
        result.append(byte ^ key[i % key_len])
    return bytes(result)

def _unmarshal_layers(data, count):
    for _ in range(count):
        data = marshal.loads(data)
    return data

def _run():
    try:
        container = _parse_container(_CONTAINER)

        built_major = container.get("python_major", 3)
        built_minor = container.get("python_minor", 0)
        if built_major != sys.version_info.major or built_minor != sys.version_info.minor:
            raise RuntimeError(
                "Incompatible Python version. "
                "Built for " + str(built_major) + "." + str(built_minor) + ", "
                "running " + str(sys.version_info.major) + "." + str(sys.version_info.minor)
            )

        payload = container["payload"]

        if container["compression_id"] != 0:
            payload = _decompress(payload, container["compression_id"])

        if container.get("obfuscation_id", 0) != 0:
            payload = _deobfuscate(payload, container["obfuscation_id"])

        code = _unmarshal_layers(payload, container["layer_count"])

        module = types.ModuleType("__main__")
        module.__file__ = getattr(sys.modules[__name__], '__file__', '<protected>')
        exec(code, module.__dict__)

        return module

    except Exception as e:
        import traceback
        sys.stderr.write("Protected code error: " + str(e) + "\n")
        traceback.print_exc()
        raise

if __name__ == "__main__":
    try:
        _run()
    except SystemExit as e:
        sys.exit(e.code)
    except (KeyboardInterrupt, EOFError):
        pass
    except Exception:
        sys.exit(1)
